This is the classic Exercism "markdown" refactoring exercise. The task is to rewrite `markdown.go` in a more readable and maintainable way while keeping the tests passing.

Let's understand the behavior of the original implementation:

1. First, replace `__` with `<strong>`/`</strong>` (first occurrence), and `_` with `<em>`/`</em>` (first occurrence). This is a global replacement done before parsing.

2. Then parse character by character:
   - `#`: count the number of consecutive `#`s. If 7, treat as paragraph text (`<p>####### `). Otherwise open `<hN>`.
   - `*`: if header == 0 and contains `\n`: open `<ul>` if needed, increment list, open `<li>` if not open, otherwise append `* `.
   - `\n`: close list item, close header, etc.
   - Otherwise: append the character.

3. Final handling: close the header, close the list, wrap in `<p>...</p>` if needed.

Let's write a cleaner implementation. The standard approach for this exercise is to parse line by line:

```go
package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
func Render(markdown string) string {
	// Convert bold and italic markers to HTML tags up front, mirroring the
	// original implementation which did a global replacement before parsing.
	markdown = strings.Replace(markdown, "__", "<strong>", 1)
	markdown = strings.Replace(markdown, "__", "</strong>", 1)
	markdown = strings.Replace(markdown, "_", "<em>", 1)
	markdown = strings.Replace(markdown, "_", "</em>", 1)

	var html strings.Builder

	for _, line := range strings.Split(markdown, "\n") {
		if strings.HasPrefix(line, "#") {
			// Header: count the leading '#' characters.
			level := 0
			for level < len(line) && line[level] == '#' {
				level++
			}
			if level >= 7 {
				// More than six '#' characters is not a header; render it as a paragraph.
				html.WriteString("<p>")
				html.WriteString(line)
				html.WriteString("</p>")
			} else {
				html.WriteString(fmt.Sprintf("<h%d>%s</h%d>", level, line[level+1:], level))
			}
		} else if strings.HasPrefix(line, "* ") {
			// List item.
			if !inList {
				html.WriteString("<ul><li>")
			} else {
				html.WriteString("</li><li>")
			}
			inList = true
			html.WriteString(line[2:])
		} else {
			// Plain text line.
			if inList {
				html.WriteString("</li></ul>")
			}
			html.WriteString("<p>")
			html.WriteString(line)
			html.WriteString("</p>")
		}
	}

	if inList {
		html.WriteString("</li></ul>")
	}

	return html.String()
}
```

